FuncDef.Code:
float opSmoothInfRepeatZ(inout vec3 p, float spacing, float smoothness)
{
    float halfsize = spacing*0.5;
    float cellIndex = floor((p.z + halfsize)/spacing);

    //p.z = mod(p.z + halfsize, spacing) - halfsize;
    p.z = modEx(p.z + halfsize, spacing, smoothness) - halfsize;

    return cellIndex;
}
